  _images: {},
  preload() {
    const keys = Object.keys(this.registry);
    return Promise.all(keys.map(key => this._loadOne(key)));
  },
  _loadOne(key) {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => { this._images[key] = img; resolve(true); };
      img.onerror = () => { resolve(false); };
      img.src = this.registry[key];
    });
  },

    leaf_0: 'data:image/png;base64,',
